import java.net.{InetAddress, DatagramPacket, DatagramSocket}
import java.util.concurrent.{ConcurrentHashMap, atomic}
import java.util.concurrent.atomic.{AtomicBoolean, AtomicReference, AtomicInteger}
import java.security.SecureRandom
import scala.collection.mutable
import scala.util.{Try, Success, Failure}

object DnsResolverConfig {
  val ENV_CACHE_TTL = "DNS_CACHE_TTL_MS"
  val ENV_MAX_RETRIES = "DNS_MAX_RETRIES"
  val ENV_RESOLVER_MODE = "DNS_RESOLVER_MODE"
  val ENV_SIGNAL_HANDLER = "DNS_SIGNAL_RELOAD"

  def cacheTtlMs: Long = sys.env.getOrElse(ENV_CACHE_TTL, "30000").toLong
  def maxRetries: Int = sys.env.getOrElse(ENV_MAX_RETRIES, "3").toInt
  def resolverMode: String = sys.env.getOrElse(ENV_RESOLVER_MODE, "recursive")
  def signalReloadEnabled: Boolean = sys.env.getOrElse(ENV_SIGNAL_HANDLER, "true").toBoolean
}

case class DnsRecord(name: String, address: String, ttl: Long, resolvedAt: Long) {
  def isExpired: Boolean = System.currentTimeMillis() - resolvedAt > ttl
}

case class ServerConfig(servers: Array[String], index: AtomicInteger)

class ResolverState {
  val cache = new ConcurrentHashMap[String, DnsRecord]()
  val pendingQueries = new ConcurrentHashMap[String, AtomicInteger]()
  val configGeneration = new AtomicInteger(0)
  val isReloading = new AtomicBoolean(false)
  // Immutable reference swap for thread safety
  val upstreamConfig = new AtomicReference[ServerConfig](
    ServerConfig(Array("8.8.8.8", "8.8.4.4"), new AtomicInteger(0))
  )
}

class DnsResolver {
  private val state = new ResolverState()
  private val shutdownFlag = new AtomicBoolean(false)
  private val reloadLock = new Object()
  // Cryptographically strong source for DNS transaction IDs
  private val secureRandom = new SecureRandom()

  def initialize(): Unit = {
    if (DnsResolverConfig.signalReloadEnabled) {
      installSignalHandler()
    }
    startCacheEvictionThread()
  }

  private def installSignalHandler(): Unit = {
    val handler = new sun.misc.SignalHandler {
      override def handle(sig: sun.misc.Signal): Unit = {
        // Signal handler only sets a flag; actual reload happens in dedicated thread
        scheduleReload()
      }
    }
    Try(sun.misc.Signal.handle(new sun.misc.Signal("USR1"), handler))
  }

  @volatile private var reloadRequested: Boolean = false

  private def scheduleReload(): Unit = {
    reloadRequested = true
  }

  // Reload runs in the eviction thread, not in signal context
  private def reloadConfiguration(): Unit = {
    reloadLock.synchronized {
      state.isReloading.set(true)
      val gen = state.configGeneration.incrementAndGet()

      // Read new upstream servers from environment
      val servers = sys.env.getOrElse("DNS_UPSTREAM_SERVERS", "8.8.8.8,8.8.4.4")
      val parsed = servers.split(",").map(_.trim).filter(_.nonEmpty)

      val validServers = if (parsed.isEmpty) Array("8.8.8.8", "8.8.4.4") else parsed

      // Atomic swap of entire config - no partial visibility
      val newConfig = ServerConfig(validServers, new AtomicInteger(0))
      state.upstreamConfig.set(newConfig)

      // Cache invalidation after config is fully consistent
      state.cache.clear()

      state.isReloading.set(false)
    }
  }

  def resolve(hostname: String): Either[String, DnsRecord] = {
    if (shutdownFlag.get()) return Left("Resolver is shut down")
    if (hostname == null || hostname.isEmpty) return Left("Invalid hostname")
    if (!hostname.matches("^[a-zA-Z0-9][a-zA-Z0-9\\-\\.]*[a-zA-Z0-9]$")) {
      return Left("Invalid hostname format")
    }

    val cached = state.cache.get(hostname)
    if (cached != null && !cached.isExpired) {
      return Right(cached)
    }

    performResolution(hostname)
  }

  private def performResolution(hostname: String): Either[String, DnsRecord] = {
    val counter = state.pendingQueries.computeIfAbsent(hostname, _ => new AtomicInteger(0))
    val attempt = counter.incrementAndGet()

    if (attempt > DnsResolverConfig.maxRetries) {
      state.pendingQueries.remove(hostname)
      return Left(s"Max retries exceeded for $hostname")
    }

    try {
      // Snapshot the config atomically - no race with reload
      val config = state.upstreamConfig.get()
      val servers = config.servers
      val idx = config.index.getAndIncrement() % servers.length
      val server = servers(Math.abs(idx))

      val result = queryUpstream(hostname, server)
      result match {
        case Right(record) =>
          state.cache.put(hostname, record)
          state.pendingQueries.remove(hostname)
          Right(record)
        case Left(err) =>
          if (!state.isReloading.get()) {
            performResolution(hostname)
          } else {
            Left("Configuration reload in progress")
          }
      }
    } catch {
      case e: Exception =>
        Left(s"Resolution failed: ${e.getMessage}")
    }
  }

  private def queryUpstream(hostname: String, server: String): Either[String, DnsRecord] = {
    val socket = new DatagramSocket()
    socket.setSoTimeout(5000)
    try {
      // Generate an unpredictable transaction ID per query to prevent spoofing
      val txId = secureRandom.nextInt(0x10000)
      val query = buildDnsQuery(hostname, txId)
      val serverAddr = InetAddress.getByName(server)
      val packet = new DatagramPacket(query, query.length, serverAddr, 53)
      socket.send(packet)

      val responseBuffer = new Array[Byte](512) // Thread-local buffer
      val response = new DatagramPacket(responseBuffer, responseBuffer.length)
      socket.receive(response)

      parseDnsResponse(hostname, responseBuffer, response.getLength, txId)
    } finally {
      socket.close()
    }
  }

  private def buildDnsQuery(hostname: String, txId: Int): Array[Byte] = {
    val buffer = new Array[Byte](512)
    buffer(0) = ((txId >> 8) & 0xFF).toByte; buffer(1) = (txId & 0xFF).toByte // Transaction ID (random)
    buffer(2) = 0x01; buffer(3) = 0x00 // Flags: standard query, recursion desired
    buffer(4) = 0x00; buffer(5) = 0x01 // Questions: 1
    var offset = 12
    hostname.split("\\.").foreach { label =>
      buffer(offset) = label.length.toByte
      offset += 1
      label.getBytes("US-ASCII").copyToArray(buffer, offset)
      offset += label.length
    }
    buffer(offset) = 0x00; offset += 1
    buffer(offset) = 0x00; buffer(offset + 1) = 0x01 // Type A
    buffer(offset + 2) = 0x00; buffer(offset + 3) = 0x01 // Class IN
    buffer.take(offset + 4)
  }

  private def parseDnsResponse(hostname: String, data: Array[Byte], length: Int, expectedTxId: Int): Either[String, DnsRecord] = {
    if (length < 12) return Left("Response too short")

    // Verify the response transaction ID matches the query to reject spoofed replies
    val respTxId = ((data(0) & 0xFF) << 8) | (data(1) & 0xFF)
    if (respTxId != expectedTxId) return Left("Transaction ID mismatch")

    val answerCount = ((data(6) & 0xFF) << 8) | (data(7) & 0xFF)
    if (answerCount == 0) return Left(s"No answers for $hostname")

    // Simplified: extract first A record
    var offset = 12
    // Skip question section
    while (offset < length && data(offset) != 0) {
      if ((data(offset) & 0xC0) == 0xC0) { offset += 2; }
      else { offset += (data(offset) & 0xFF) + 1 }
    }
    offset += 5 // null terminator + type + class

    if (offset + 12 > length) return Left("Malformed response")
    offset += 2 // name pointer
    offset += 2 // type
    offset += 2 // class
    val ttl = ((data(offset) & 0xFFL) << 24) | ((data(offset+1) & 0xFFL) << 16) |
              ((data(offset+2) & 0xFFL) << 8) | (data(offset+3) & 0xFFL)
    offset += 4
    val rdLength = ((data(offset) & 0xFF) << 8) | (data(offset+1) & 0xFF)
    offset += 2

    if (rdLength == 4 && offset + 4 <= length) {
      val addr = s"${data(offset) & 0xFF}.${data(offset+1) & 0xFF}.${data(offset+2) & 0xFF}.${data(offset+3) & 0xFF}"
      Right(DnsRecord(hostname, addr, ttl * 1000, System.currentTimeMillis()))
    } else {
      Left("Unsupported record type")
    }
  }

  private def startCacheEvictionThread(): Unit = {
    val thread = new Thread("dns-cache-eviction") {
      override def run(): Unit = {
        while (!shutdownFlag.get()) {
          Thread.sleep(DnsResolverConfig.cacheTtlMs / 2)
          if (reloadRequested) {
            reloadRequested = false
            reloadConfiguration()
          }
          evictExpiredEntries()
        }
      }
    }
    thread.setDaemon(true)
    thread.start()
  }

  private def evictExpiredEntries(): Unit = {
    val iter = state.cache.entrySet().iterator()
    while (iter.hasNext) {
      val entry = iter.next()
      if (entry.getValue.isExpired) {
        iter.remove()
      }
    }
  }

  def shutdown(): Unit = {
    shutdownFlag.set(true)
    state.cache.clear()
  }
}

object DnsResolverApp extends App {
  val resolver = new DnsResolver()
  resolver.initialize()

  val testDomains = List("example.com", "google.com", "github.com")
  testDomains.foreach { domain =>
    resolver.resolve(domain) match {
      case Right(record) => println(s"Resolved $domain -> ${record.address}")
      case Left(error) => println(s"Failed to resolve $domain: $error")
    }
  }

  resolver.shutdown()
}
